import type { BlogPost } from './types';
import type { ResearchPost } from './types';

export const november08BlogPosts: readonly BlogPost[] = [{"slug":"build-a-prebill-cut-off-calendar-partners-will-follow","title":"Build a prebill cut-off calendar partners will follow","description":"A working cut-off calendar that separates client deadlines, internal review windows, and release dates so prebill work stops arriving late.","category":"Prebill","readTime":"7 min read","thumbnail":"/thumbnails/november-08/build-a-prebill-cut-off-calendar-partners-will-follow.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/prepare-a-prebill-packet-for-a-partners-fifteen-minute-review","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Why a written cut-off beats a reminder email","paragraphs":["A prebill cut-off fails when the date exists only in a reminder email that arrives after the work has already slipped. Partners plan around client meetings, court dates, and travel, so a date that appears once in an inbox does not shape their week. A published calendar gives every person the same reference point and makes lateness visible before it becomes a client problem. The calendar is a coordination tool, not a punishment schedule.","The calendar also protects the billing team from absorbing every delay as unpaid overtime. When release dates are explicit, a late time entry becomes an exception with a named owner rather than a silent scramble. Reviewers can plan capacity across matters instead of reacting to whichever partner calls first. A short calendar with reliable dates is more useful than a detailed policy nobody reads."]},{"heading":"Map the dates that actually constrain the calendar","paragraphs":["Start with the client deadlines that carry consequences: e-billing submission windows, outside counsel guideline cut-offs, accrual requests, and payment terms. Record the source document and the person who confirmed each date. Distinguish a hard deadline from a preferred date, because treating every date as urgent destroys credibility. The calendar should show which dates can move and who can authorize a change.","Then add the internal dates that make the client deadline achievable. A partner review window, a conflicts check, a rate approval step, and a final quality sample all consume days before release. Work backward from the client date and mark each internal milestone. If the backward plan leaves less than one business day for review, the calendar is already telling you that capacity or scope must change."]},{"heading":"Separate client deadlines from internal review windows","paragraphs":["A client deadline belongs to the client relationship owner and should not be renegotiated by an assistant. An internal review window belongs to the firm and can be adjusted when the partner is unavailable. Mixing the two on one list makes every internal change look like a client concession. Use separate columns and separate escalation paths so the distinction survives a busy week.","Label each date with the action required, not just the date itself. A line that says client submits by the tenth is less useful than a line that says final partner approval must be recorded by the fifth. The action label tells the reader what to do and who must do it. Dates without actions become decoration that everyone acknowledges and nobody follows."]},{"heading":"Publish the calendar in the tools people already use","paragraphs":["Put the calendar where the work happens: the matter management system, the shared billing calendar, and the prebill queue view. A separate spreadsheet that only the billing team opens will not influence partner behavior. Mirror the dates in the tools that partners and legal assistants already check each morning. Consistency across two or three surfaces is enough; a dozen copies create version drift.","Keep one controlled version and give every other view a read-only feed from it. When a date changes, the change should appear once and propagate, not require five manual edits. Record the date of the last update beside the calendar so readers know they are looking at a current version. A visible update stamp prevents old screenshots from becoming the source of a dispute."]},{"heading":"Define the exception path before the first miss","paragraphs":["A cut-off calendar needs a short exception process that names who can approve a late addition and what evidence is required. The request should include the reason, the amount at risk, the client impact, and the new completion date. Approvals should be recorded in the same place as the original date so the history stays intact. An exception path that lives in private messages cannot be audited.","Set a threshold for what counts as routine versus material. A single late line that can be reviewed the same day may need only a queue note, while a missing matter packet may require partner approval. Publishing the threshold reduces arguments about consistency. The goal is to make exceptions deliberate and visible, not to eliminate every late change."]},{"heading":"Assign owners for each calendar milestone","paragraphs":["Every milestone needs one accountable owner and one backup who can act during leave. The owner is the person who confirms completion, not the person who happens to be copied on the message. Write the role rather than a single name so the calendar survives turnover. A milestone with two equal owners usually has none.","Owners should report completion with evidence, such as a timestamped approval or a linked queue record. A simple checkbox without evidence cannot support a later audit or a client question. The calendar should show the evidence link beside each completed milestone. When evidence is missing, the milestone is not complete even if someone remembers doing the work."]},{"heading":"Review the calendar after every close","paragraphs":["After each billing cycle, compare the planned dates with the actual completion dates and note where the gap opened. Look for patterns by matter type, partner, client, and queue rather than blaming a single late event. A review that produces one specific change is more valuable than a long discussion of general busyness. Record the change and the owner who will implement it.","Use the review to adjust the calendar only when the evidence supports a structural change. Moving every date later because one month was difficult teaches the team that deadlines are negotiable. Instead, fix the bottleneck that caused the delay, such as an approval step with no backup. The calendar should become more realistic over time, not simply more forgiving."]},{"heading":"Keep the calendar stable across holidays and leave","paragraphs":["Holiday weeks and planned leave distort a calendar that assumes five full business days every week. Mark known closures and coverage gaps on the calendar before the cycle begins, then shift internal milestones rather than the client deadline. A backup owner should be named for each affected window. The point is to protect the commitment, not to pretend the disruption does not exist.","For unplanned leave, use the exception path and record the coverage decision in the same calendar history. Do not quietly move a date and hope no one notices, because the client and the partner may still be working from the old version. A brief note that explains the change and the new owner prevents confusion later. Stability comes from clear handling of change, not from refusing to change."]}],"faq":[{"q":"Who owns the prebill cut-off calendar?","a":"The billing manager or prebill queue owner should own the controlled version. Partners own the review milestones assigned to them, and the client relationship owner confirms external deadlines. A named backup should maintain the calendar during leave."},{"q":"How many dates should the calendar show?","a":"Show only the dates that change behavior: client submission, partner approval, quality review, release, and any accrual or reporting deadline. A short list that people use is better than a complete policy calendar that nobody checks."},{"q":"What should happen when a partner misses a review window?","a":"Record the miss, notify the named backup, and use the exception path to agree on a new completion date. If the client deadline is at risk, escalate to the relationship owner immediately. Review the cause after the close rather than arguing about it in the moment."}],"publishedAt":"2026-11-08"},{"slug":"screen-a-new-matter-for-billing-setup-before-the-first-time-entry","title":"Screen a new matter for billing setup before the first time entry","description":"An intake screen that catches missing rates, guidelines, contacts, and e-billing enrollment before work begins and before the first invoice stalls.","category":"Matter records","readTime":"8 min read","thumbnail":"/thumbnails/november-08/screen-a-new-matter-for-billing-setup-before-the-first-time-entry.webp","internalService":"/services/matter-record-upkeep","internalSibling":"/blog/create-a-matter-billing-contact-sheet-for-faster-escalation","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Why billing setup belongs at intake","paragraphs":["Most billing problems that appear at the first invoice were created when the matter opened. A missing rate, an unrecorded client guideline, or an e-billing enrollment that was never completed can take weeks to resolve after the work is done. The person opening the matter often has the client conversation in hand, which makes intake the cheapest moment to capture the facts. Waiting until prebill turns a simple question into a dispute.","An intake screen is not a substitute for the engagement letter or the firm's conflicts process. It is a short operational check that confirms the billing infrastructure exists before time is entered. The screen should take minutes, not hours, and should produce a clear list of what is missing and who owns each item. A matter that opens with unresolved billing facts should be flagged, not silently released to the team."]},{"heading":"Confirm the client entity and billing contact","paragraphs":["Record the exact legal entity that will receive the invoice, not just the familiar client name. Large organizations often have separate entities, billing centers, and payment offices, and an invoice sent to the wrong entity can restart the entire approval process. Capture the billing contact, the accounts payable contact, and the person who can answer a guideline question. Include a phone number and a shared mailbox where possible.","Verify that the contact information is current before the first invoice is prepared. A name copied from an old matter may belong to someone who left the client two years ago. Ask the relationship owner to confirm the active contact and the preferred channel. Store the confirmation date beside the contact so a later reviewer can judge whether the record is still trustworthy."]},{"heading":"Capture rates and any client rate conditions","paragraphs":["Record the agreed rates by timekeeper and effective date, including any blended rate, discount, cap, or fixed fee. Note whether the client requires prior approval for rate increases and who grants it. A rate that is correct in the billing system but inconsistent with the engagement letter creates a correction at the worst possible time. Attach the source document or link to the approved rate record.","Distinguish standard rates from matter-specific arrangements and from client-wide agreements. A matter may inherit a client rate card but still carry a special cap for a particular phase of work. Write those conditions in plain language beside the rate fields so a reviewer does not have to interpret a contract. If a condition is unclear, mark it unresolved and assign an owner rather than guessing."]},{"heading":"Log the client billing guidelines and their version","paragraphs":["Save the client billing guidelines in a controlled location and record the version and effective date. Summarize the rules that change daily work, such as time increments, narrative requirements, travel time, staffing, and expenses. Link the summary to the source document so a reviewer can verify the original language. A summary without the source is an opinion, not evidence.","Record any known exceptions or negotiated deviations and who approved them. A client may waive a rule for a specific matter or phase, and that exception needs to survive staff changes. Note the expiration date if the exception is temporary. Review the guideline version again at the first prebill to catch a policy that changed after intake."]},{"heading":"Verify e-billing enrollment and submission access","paragraphs":["Confirm whether the client requires e-billing, which vendor platform is used, and whether the firm has an active account for this client. Check that the matter has the correct client and matter identifiers before the first submission. Enrollment problems are much easier to fix before a deadline than after an invoice is rejected at the portal. Record the vendor contact and the firm's account administrator.","Test the submission path with a small sample or a draft invoice when the vendor allows it. Confirm that the firm's timekeepers and rate codes map to the client's requirements. Note any required LEDES fields or special invoice formats. If the enrollment is incomplete, set a dated follow-up and tell the billing team that the first invoice may be delayed."]},{"heading":"Record budget, accrual, and reporting expectations","paragraphs":["Ask whether the client requires a budget, a phase plan, accrual reporting, or a monthly status report. Record the format, the due date, and the person who receives it. These requirements often live in a separate client protocol that never reaches the billing team. A matter that needs an accrual number but has no reporting owner will produce a late estimate.","Clarify how budget changes are approved and how often the client expects an update. Some clients want a formal revision, while others accept a note in the monthly report. Write the expectation in the matter record and link the template. The billing team should know before the first month closes whether it is preparing a number, a narrative, or both."]},{"heading":"Flag trust, expense, and third-party billing issues","paragraphs":["Identify whether the matter involves a trust retainer, client costs, or third-party payer arrangements. Record the trust account, the replenishment threshold, and the person who monitors the balance. Expense handling should be confirmed at intake because a client may require receipts, pre-approval, or a specific cost code. These details are difficult to reconstruct after the fact.","If a third-party payer or insurer is involved, record the billing entity, the authorization, and any required reference number. Confirm whether the invoice goes to the payer or to the client and whether both need a copy. A wrong routing decision can delay payment by weeks. The intake screen should make the routing explicit rather than leaving it to memory."]},{"heading":"Close the screen with named gaps and owners","paragraphs":["End the intake screen with a short list of unresolved items, each with an owner and a due date. Mark the matter as ready for time entry only when the core billing facts are confirmed or the risk is accepted by an authorized person. A partial setup can proceed if the gaps are visible and tracked. The danger is an invisible gap that surfaces at prebill.","Review the screen at the first prebill and update any field that changed. Intake is a starting point, not a permanent record. Note the review date and the person who confirmed the update. A matter that is rechecked once before the first invoice catches most of the errors that would otherwise become write-downs or collection delays."]}],"faq":[{"q":"What is the minimum billing setup for a new matter?","a":"At minimum, record the billing entity, billing contact, rates, matter identifier, client guidelines, and e-billing requirement. Add budget, accrual, trust, and third-party payer details when they apply. Name an owner for any item that cannot be confirmed at intake."},{"q":"Should the billing assistant open the matter?","a":"The assistant can collect and verify billing facts, but the firm's authorized person should open the matter and approve rates or exceptions. Keep the role boundary explicit so administrative preparation does not become an unauthorized decision."},{"q":"How soon should the screen be repeated?","a":"Repeat the relevant fields at the first prebill and whenever the client changes guidelines, contacts, or rates. A full re-screen is usually unnecessary, but the review date and source should be recorded so the record is not treated as permanently current."}],"publishedAt":"2026-11-08"},{"slug":"turn-a-partners-verbal-billing-instruction-into-a-written-record","title":"Turn a partner's verbal billing instruction into a written record","description":"A confirmation routine that converts hallway instructions into a dated, reviewable record before they reach the prebill or the client.","category":"Role design","readTime":"7 min read","thumbnail":"/thumbnails/november-08/turn-a-partners-verbal-billing-instruction-into-a-written-record.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/write-a-client-billing-guideline-summary-an-assistant-can-use","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Why verbal instructions create billing risk","paragraphs":["A partner often gives billing direction in a hallway, on a call, or in a short message that assumes context the assistant does not have. The instruction may be clear in the moment and ambiguous an hour later, especially when it involves a write-down, a rate change, or a narrative standard. Without a written record, the assistant must guess or interrupt the partner again. Both outcomes cost time and create avoidable errors.","The risk is not that partners are careless. The risk is that informal instructions are optimized for speed and not for auditability. A later reviewer cannot tell whether the instruction applied to one line, one matter, or the whole client. A short confirmation note closes that gap without turning every conversation into a formal memo."]},{"heading":"Capture the instruction while the context is fresh","paragraphs":["Write the note immediately after the conversation, using the partner's words where possible and a plain summary where not. Record the date, time, channel, and participants so the source is traceable. Include the matter, the timekeepers, and the specific lines or period affected. A note written a week later is a reconstruction, not a record.","Ask one clarifying question if the scope is unclear, rather than filling the gap with an assumption. For example, confirm whether a reduced rate applies to all work in the matter or only to a defined phase. The answer should be captured in the same note. A brief pause at the point of instruction prevents a much longer correction at prebill."]},{"heading":"State the action in operational language","paragraphs":["Translate the instruction into the fields the billing system actually uses: rate, hours, narrative, write-down amount, approval path, or client communication. Avoid recording only the partner's conclusion, such as make this reasonable, because that phrase does not tell a reviewer what to change. Write the specific action and the evidence that supports it. A reviewer should be able to read the field and know exactly what to change.","If the instruction requires a judgment, name the person who owns that judgment and the basis they used. A note that says the partner approved a courtesy reduction is weaker than one that records the amount, the reason, and the client context. The operational version lets another reviewer apply the same logic consistently. Record the basis beside the decision so the reasoning survives a staff change."]},{"heading":"Separate the decision from the execution","paragraphs":["Record what was decided, who decided it, and what still needs to happen before the invoice changes. The partner may approve a write-down while the billing assistant still needs to update the time entry, notify the client, and adjust the prebill. Keeping decision and execution separate prevents a note from looking complete when the work is only half done. The execution list should name the next owner and the date the step is due.","Assign the execution steps to named owners with dates. If the partner's instruction depends on a client guideline or an engagement letter, note the source that was checked. If the source was not checked, mark it as an open item rather than implying approval. A clear execution list turns a conversation into a workflow."]},{"heading":"Confirm the note back to the partner","paragraphs":["Send a short confirmation that states the action in one or two sentences and invites a correction. Keep it easy to answer, such as a reply with confirmed or a specific change. Do not bury the request in a long recap that the partner will skim. The goal is a fast, durable agreement on the record.","If the partner does not respond, treat the note as pending rather than approved for any action that changes a client invoice. Set a follow-up date and escalate through the agreed path if the matter is time-sensitive. Silence is not authorization for a billing adjustment. The confirmation rule should be written into the role brief so everyone applies it the same way."]},{"heading":"Link the note to the matter and the invoice","paragraphs":["Store the confirmation in the matter record or the billing file, not in a personal inbox. Link it to the relevant time entries and the prebill packet so a reviewer can find the source without searching. Use a consistent naming convention that includes the matter and the date. A note that cannot be found is functionally the same as no note.","When the invoice is prepared, reference the instruction in the review notes or the adjustment record. That reference lets a later auditor connect the change to the approval. If the client asks about the adjustment, the team can respond with evidence rather than recollection. The link is the difference between a documented decision and an unexplained write-down."]},{"heading":"Handle instructions that conflict with client rules","paragraphs":["Sometimes a partner asks for something the client guideline does not permit, such as a narrative style the client has rejected or a rate above the agreed cap. Record the conflict in the note and pause the change until the relationship owner resolves it. Do not silently follow the partner and hope the client accepts the result. The assistant's role is to surface the conflict, not to choose which rule wins.","Document the resolution, including who spoke with the client and what was agreed. If the client grants an exception, record its scope and expiration. If the partner decides to absorb the difference internally, record that decision and the approver. Either way, the written record should show why the final action is defensible."]},{"heading":"Review the routine after a difficult close","paragraphs":["After a close with several verbal instructions, review whether the notes captured enough detail to prevent rework. Look for the instructions that required a second conversation or produced a correction. That pattern shows where the confirmation template needs another field. Update the template rather than asking people to remember more.","Share one anonymized example with the billing team so the standard is concrete. A good example shows the original words, the operational translation, the approval, and the final invoice action. The team can copy the structure without copying the content. Over time, the routine becomes part of how the firm handles billing decisions, not an extra step added at the end."]}],"faq":[{"q":"Does every verbal instruction need a written note?","a":"Any instruction that changes a rate, write-down, narrative, approval path, or client communication should be recorded. Routine scheduling or formatting requests may not need the same treatment. Use the risk of a later dispute to decide."},{"q":"Who should write the confirmation?","a":"The person who received the instruction should write it while the context is fresh, then send it to the partner for confirmation. The billing manager should review the routine and the template, not every individual note."},{"q":"What if the partner refuses to confirm in writing?","a":"Record that the instruction was given verbally and note the date and participants. Escalate through the billing manager if the change is material. Do not treat an unconfirmed instruction as final authorization for a client invoice adjustment."}],"publishedAt":"2026-11-08"},{"slug":"prepare-a-write-off-request-packet-finance-can-approve-in-one-pass","title":"Prepare a write-off request packet finance can approve in one pass","description":"A packet structure that gives finance the amount, cause, client basis, and prevention step needed to approve a write-off without another meeting.","category":"Write-offs","readTime":"8 min read","thumbnail":"/thumbnails/november-08/prepare-a-write-off-request-packet-finance-can-approve-in-one-pass.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/turn-write-off-patterns-into-a-monthly-coaching-agenda","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"Why write-off packets stall","paragraphs":["A write-off request usually stalls because the approver cannot see the whole story in one place. The request may show an amount and a short reason, but not the original charge, the client rule, the prior approval, or the step that will prevent a repeat. Finance then has to ask for missing evidence, and the request waits in a queue while the billing team answers one question at a time. A one-page structure removes most of that delay before the request is submitted.","A complete packet does not guarantee approval, but it makes the decision possible in one review. The approver should be able to see what happened, why the charge cannot be collected, who is accountable, and what changes next. That structure also protects the firm if the write-off is later questioned by a client or an auditor. Finance should not have to reconstruct the story from separate messages or spreadsheets."]},{"heading":"State the amount and the affected lines","paragraphs":["Begin with the total requested amount and a line-level breakdown that ties back to the invoice or prebill. Show the original charge, the proposed adjustment, and the resulting net amount. Include the matter, client, timekeeper, and date for each line. A total without the underlying lines is impossible to verify.","Separate a true write-off from a courtesy discount, a rate correction, or an uncollectible balance. Each category follows a different approval path and has a different accounting treatment. Label the request accurately so finance does not have to reclassify it. If the request contains more than one category, split it into separate sections with separate totals."]},{"heading":"Explain the client basis with evidence","paragraphs":["Quote or summarize the client rule, guideline, or communication that supports the adjustment. Link the source document and note the version or date. If the basis is a verbal client concession, record who granted it and when. Finance should not have to infer the client's position from a general statement that the charge was disputed.","Distinguish a client-driven adjustment from an internal quality decision. A client may refuse a charge because the narrative was insufficient, while the firm may write off a charge because a timekeeper made an error. The two have different prevention paths. Naming the basis correctly makes the rest of the packet more useful."]},{"heading":"Show the approval history","paragraphs":["List every approval already obtained, including the partner, billing manager, and client contact where relevant. Include the date and the scope of each approval. A packet that says the partner approved but does not show what they approved invites a second review. The approver should be able to see that authority was exercised at the right level.","If an approval is missing, say so explicitly and name the person who will obtain it. Do not imply consent that has not been given. A clear gap is easier to resolve than a vague assertion that everyone is on board. The packet should make the remaining step obvious."]},{"heading":"Identify the cause without assigning blame","paragraphs":["Describe the operational cause in specific terms: a missing narrative component, a rate not loaded at intake, a duplicate entry, or a client guideline change that was not logged. Avoid labeling the cause as a person's mistake, because blame shuts down the information needed to prevent a repeat. The approver needs the mechanism, not a culprit. A neutral description keeps the focus on the process that needs to change.","Use a small set of cause codes so patterns can be counted across requests. Include an other category with a required note, and review the codes quarterly. A cause code that nobody uses is worse than no code because it creates false precision. The packet should show the code and the evidence behind it."]},{"heading":"Name the prevention step and its owner","paragraphs":["Every write-off packet should include one realistic prevention step with an owner and a date. The step may be a checklist change, a training note, a rate load, or a client clarification. It should address the cause identified in the packet, not restate the general goal of better quality. A prevention plan that cannot be implemented is filler.","If the same cause appears repeatedly, say so and link the prior requests. A pattern is more persuasive than a single promise to be careful. The owner should confirm the step is complete before the next cycle. Finance can then see that the write-off is connected to a control rather than treated as an isolated loss."]},{"heading":"Anticipate the approver's questions","paragraphs":["Add a short section that answers the questions finance usually asks: Was the client notified, is the amount within the approver's limit, does the adjustment affect a budget or accrual, and is there any chance of collection. Answer each one directly with a link to evidence. The goal is to remove the back-and-forth that lengthens the queue. A short, direct answer is easier to approve than a paragraph that repeats the request.","If a question cannot be answered, state what is unknown and who is finding out. An honest open item is better than a confident guess that later proves wrong. The approver can decide whether to wait or approve conditionally. A packet that hides uncertainty creates more risk than one that names it."]},{"heading":"Close the loop after the decision","paragraphs":["Record the final decision, the approved amount, and the date in the same file as the request. Update the invoice or accounting record and confirm the adjustment posted correctly. Send a short outcome note to the people who provided evidence so the process does not feel like a black hole. A closed loop encourages better packets next time.","Review a sample of approved and rejected packets each quarter to see which sections are missing or unclear. Use the results to simplify the template rather than add more fields. The best packet is the shortest one that lets an approver decide with confidence. Keep refining toward that standard."]}],"faq":[{"q":"What belongs in a write-off request packet?","a":"Include the total and line-level amounts, the client or quality basis with evidence, the approval history, the cause, the prevention step and owner, and answers to the approver's common questions. Link every claim to a source record."},{"q":"Who should approve a write-off?","a":"Approval limits should be set in writing by the firm and applied by amount, category, and client sensitivity. The packet should show that the request is at the correct level. An assistant can prepare the packet but should not approve the adjustment."},{"q":"How do we stop repeat write-offs?","a":"Code the cause consistently, review the codes quarterly, and assign one prevention step per material cause. Track whether the step was implemented before the next cycle. A pattern review is more useful than a general reminder to be careful."}],"publishedAt":"2026-11-08"},{"slug":"build-a-shared-billing-inbox-triage-routine-that-keeps-owners-visible","title":"Build a shared billing inbox triage routine that keeps owners visible","description":"A daily triage routine for a shared billing inbox that assigns owners, catches duplicates, and escalates time-sensitive client messages before they age.","category":"Invoice follow-up","readTime":"7 min read","thumbnail":"/thumbnails/november-08/build-a-shared-billing-inbox-triage-routine-that-keeps-owners-visible.webp","internalService":"/services/invoice-follow-up","internalSibling":"/blog/design-an-invoice-follow-up-log-that-survives-turnover","source":{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},"sections":[{"heading":"Why a shared inbox needs a triage routine","paragraphs":["A shared billing inbox becomes a hidden queue when everyone can see the messages and no one owns the next action. Messages are read, starred, forwarded, and then forgotten, while the sender believes the request is being handled. The result is duplicate work, missed deadlines, and a growing sense that the team is always behind. A short triage routine replaces that ambiguity with visible ownership.","Triage is not the same as answering every message immediately. It is the practice of classifying each message, assigning an owner, and setting a next action within a defined window. The routine should take minutes and produce a queue that anyone can read. A good routine makes it obvious what is waiting, who has it, and when it is due."]},{"heading":"Define the labels and what each one means","paragraphs":["Use a small set of labels that map to real work: client question, invoice dispute, payment confirmation, internal approval, guideline update, and vendor notice. Define each label with one example and one exclusion so the team applies it consistently. A label that means different things to different people creates a false sense of organization. The label set should be reviewed when the work changes.","Add a priority marker only where the deadline is real, such as a same-day client response or an e-billing rejection window. Do not mark every message urgent, because a queue where everything is urgent has no priority at all. The label and the priority should be separate fields. A message can be important without being due today."]},{"heading":"Set a first-response standard that is realistic","paragraphs":["Define how quickly a message must receive a first response, not how quickly it must be fully resolved. A same-business-day acknowledgement is often enough to reassure the sender and create time for the real work. The standard should distinguish client messages, internal messages, and vendor notices. Publish the standard where the team and the requesters can see it.","Measure the standard with the actual message timestamps rather than memory. Review a sample each week to see whether the standard is achievable with current coverage. If it is not, change the standard or add capacity, but do not quietly ignore it. A standard that is repeatedly missed teaches the team that commitments are optional."]},{"heading":"Make ownership visible on every message","paragraphs":["Every triaged message should show one owner, one next action, and one due date. The owner is the person who will move the work forward, not the person who happened to open it first. Use the shared inbox assignment feature or a linked queue record so the owner is visible without opening a private note. An unassigned message should be treated as a gap, not a shared responsibility.","When ownership changes, record the handoff and the reason in the same thread. Do not let a message drift between people through forwards and side conversations. A named owner can still ask for help, but the accountability stays clear. The team should be able to answer who has this message in one glance."]},{"heading":"Handle duplicates and forwarded threads","paragraphs":["Duplicates arrive when a client sends the same request to a person and to the shared inbox, or when an internal colleague forwards a thread that is already being handled. Give the team a simple rule: search the matter and the sender before creating a new item. If a duplicate exists, link the messages and keep one owner. Closing the duplicate with a reference prevents two people from answering differently.","Forwarded threads often lose the attachment or the original recipient. Ask the forwarder to include the full thread or the relevant attachment, and record the source in the queue item. If the forwarded content is incomplete, request the missing piece before promising a response. A duplicate handled twice is wasteful, but two inconsistent answers are worse."]},{"heading":"Escalate before the deadline, not after","paragraphs":["Define the triggers that require escalation: an approaching client deadline, a disputed amount above a threshold, a message from an executive or key client, or a request that no one on the team can answer. The trigger should name the escalation owner and the channel. Escalation is a normal part of triage, not evidence that someone failed. A clear trigger also prevents the team from escalating everything or nothing.","Set the escalation time relative to the deadline, not to the day the message was received. A request that arrives with two days of lead time needs a different path from one that arrives on the due date. The queue should show the deadline prominently. Early escalation protects options that disappear once the deadline passes."]},{"heading":"Close the day with a short handoff","paragraphs":["End the day with a brief handoff that lists open client messages, promises made, and anything due before the next shift. Keep it short enough to read in a few minutes and specific enough to act on. The handoff should live in the shared queue, not in a private message that disappears when someone is away. A consistent handoff reduces the chance that a promise is forgotten overnight.","Include the owner and the next action for each open item, not just the subject line. If a message is waiting on a partner or a client, say so and record the follow-up date. The next person should not have to reconstruct the history. A good handoff is a continuation of the work, not a status report about it."]},{"heading":"Review the routine monthly with real samples","paragraphs":["Each month, review a sample of messages from intake to resolution and check whether the labels, owners, and response times held up. Look for messages that were reopened, reassigned repeatedly, or closed without a recorded outcome. Those cases show where the routine is too vague or the coverage is too thin. Use real examples, with client details removed, to train the team.","Change one part of the routine at a time and observe the effect for a full cycle. Adding labels without fixing ownership usually creates more work without improving service. The review should end with a specific change and an owner. Over time, the routine should become simpler and more reliable, not more elaborate."]}],"faq":[{"q":"How many labels should a billing inbox use?","a":"Use the smallest set that matches the work, usually five to eight labels. Each label needs a definition and an example so the team applies it consistently. Review the set when the queue changes."},{"q":"Who owns the shared inbox?","a":"A named queue owner should be accountable for triage coverage and response standards, with backups for leave. Individual messages still need one owner each. The queue owner does not have to answer every message."},{"q":"What is a realistic first-response standard?","a":"A same-business-day acknowledgement is often realistic for client messages, with resolution times depending on the request. Measure the actual timestamps and adjust the standard or the coverage when it is consistently missed."}],"publishedAt":"2026-11-08"},{"slug":"audit-a-billing-data-retention-schedule-before-an-office-move","title":"Audit a billing data retention schedule before an office move","description":"A practical audit that finds expired records, legal holds, and access gaps before boxes are packed and billing history is lost in a move.","category":"Records","readTime":"8 min read","thumbnail":"/thumbnails/november-08/audit-a-billing-data-retention-schedule-before-an-office-move.webp","internalService":"/services/matter-record-upkeep","internalSibling":"/blog/prepare-a-billing-continuity-binder-before-planned-leave","source":{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},"sections":[{"heading":"Why a move exposes retention gaps","paragraphs":["An office move forces a firm to touch records that have been sitting in cabinets, shared drives, and personal folders for years. Boxes get packed quickly, labels are simplified, and the person who knew what a folder contained may be on vacation. A record that should have been destroyed can travel to the new office, while a record under legal hold can be misplaced. The move is a rare chance to fix the schedule, but only if the audit happens first.","Retention is not only about deleting old paper. It covers email, billing exports, trust records, client portals, and backup copies. A move changes the physical and digital location of all of them, which makes access and ownership harder to verify afterward. The audit should produce a clear inventory and a decision for every record category before anything is packed."]},{"heading":"Inventory where billing records live","paragraphs":["List every location that holds billing records: matter management, accounting, e-billing portal exports, shared drives, email archives, paper files, and vendor-hosted systems. For each location, record the system owner, the retention rule, and the access method. Include the informal locations that people actually use, such as desktop folders and scanning queues. A record that is not in the inventory cannot be protected or disposed of deliberately.","Walk the physical space and the shared drive structure rather than relying on the policy diagram. Note duplicate copies, orphaned folders, and boxes without labels. Ask the people who do the work where they keep the records they use most. The gap between the official system and the working system is where retention failures usually hide."]},{"heading":"Map record types to retention rules","paragraphs":["Group records by type: client invoices, time entries, trust ledgers, expense receipts, billing guidelines, engagement letters, and correspondence. For each type, identify the retention period and the source of the rule. The source may be a firm policy, a client agreement, a tax requirement, or a professional obligation. Record the citation so the schedule can be defended later.","Distinguish the minimum retention period from the period the firm actually keeps the record. Some records are kept longer for client service or dispute history, and that decision should be explicit. A schedule that says keep everything forever is not a retention schedule. It is a storage cost with no disposal discipline."]},{"heading":"Separate active files from archived files","paragraphs":["Active files are still needed for current work, client questions, or open matters. Archived files are closed but retained for the required period. Mark each box and each folder as active or archived before packing, and record the destruction eligibility date. The distinction prevents a closed file from being treated as current and prevents an active file from being sent to deep storage.","Use a simple label that includes the client or matter, the record type, the date range, and the destruction date. Avoid vague labels such as old billing or miscellaneous. If a box contains mixed record types with different retention periods, split it or list the contents. A mixed box cannot be destroyed safely without opening it again."]},{"heading":"Protect legal holds and privileged material","paragraphs":["Before any disposal, confirm whether the firm has a legal hold, audit, or investigation that covers the records. A hold overrides the normal retention schedule and should be recorded in the inventory. Identify the hold owner and the scope so packers know which boxes must not be destroyed or moved without approval. A hold that exists only in a lawyer's memory is not a control.","Privileged material needs the same care during a move. Limit access to boxes that contain legal advice, client confidences, or personnel records. Use sealed containers and a named custodian for the move. Record the chain of custody so the firm can show who had access at each step. The move should not create a new opportunity for a confidentiality breach."]},{"heading":"Control access during packing and transport","paragraphs":["Pack records in a controlled sequence, with a named person responsible for each room or system. Keep an access log for the packing area and for any vendor that handles boxes. Do not let movers or temporary staff open sealed records without supervision. The same rule applies to digital exports: use a controlled transfer method and delete temporary copies after the move.","Label boxes with a unique identifier and record the destination in the inventory. Photograph the sealed boxes and the storage location as evidence. If a box cannot be accounted for, treat it as a missing record and start the response immediately. A move is chaotic by nature, so the controls must be simple enough to follow under pressure."]},{"heading":"Plan secure disposal for expired records","paragraphs":["Records past their retention date should be destroyed through an approved method, not simply thrown away. Use cross-cut shredding or a certified destruction vendor for paper, and a documented deletion process for digital records. Obtain a certificate of destruction and record the date, the record type, and the approver. Disposal is a controlled event, not a cleanup afterthought.","Check for duplicates before destroying a record, because one copy may be the only complete version. Confirm that the record is not under a hold and that no open matter or client request depends on it. If there is any doubt, keep the record and document the reason. The cost of keeping an extra box for a year is usually lower than the cost of losing a record that is needed."]},{"heading":"Verify the schedule after the move","paragraphs":["After the move, spot-check the inventory against the new locations and confirm that the boxes and digital folders arrived where the schedule says they should be. Test access to the systems that hold billing records, including the e-billing portal and the accounting archive. Update the inventory with any changes and record the verification date. A move is not complete until the records are findable again.","Review the audit findings with the billing manager, the records owner, and the person responsible for the new space. Identify the one or two changes that would prevent the same gaps next time, such as a better label or a quarterly inventory check. Assign an owner and a date. The next move should start with a current schedule, not another scramble."]}],"faq":[{"q":"When should the retention audit start?","a":"Start at least one full cycle before the move, ideally several weeks, so there is time to identify holds, separate active and archived files, and arrange secure disposal. Waiting until packing week limits every option."},{"q":"Can expired records simply be discarded during the move?","a":"No. Expired records should go through an approved destruction process with a record of the date, method, and approver. Confirm that no legal hold or open matter applies before destroying anything."},{"q":"Who owns the retention schedule?","a":"The firm should name a records owner, often in operations or compliance, with the billing manager confirming billing-specific rules. The schedule needs an owner who can approve exceptions and verify disposal."}],"publishedAt":"2026-11-08"},{"slug":"handle-a-client-billing-guideline-conflict-without-stalling-the-prebill","title":"Handle a client billing guideline conflict without stalling the prebill","description":"A decision path for conflicting client billing rules that keeps the prebill moving while preserving evidence and the client relationship.","category":"Billing guidelines","readTime":"7 min read","thumbnail":"/thumbnails/november-08/handle-a-client-billing-guideline-conflict-without-stalling-the-prebill.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/build-a-client-billing-guideline-change-log","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"How billing guideline conflicts appear","paragraphs":["A conflict appears when two client requirements cannot both be satisfied, or when a client rule contradicts the firm's own policy or a partner's instruction. One guideline may require daily time entries while another requires a single monthly submission. A rate card may cap a rate that a partner has already quoted higher. The conflict is usually discovered at prebill, when the invoice is already built and the deadline is close.","The worst response is to pick a rule silently and hope no one notices. That approach creates an unexplained adjustment, a client dispute, or a write-down that could have been avoided. A better path separates the immediate prebill decision from the longer-term clarification. The team can keep moving while the conflict is resolved on the record."]},{"heading":"Detect the conflict before the prebill is built","paragraphs":["Add a conflict check to the prebill preparation routine using the client's guideline summary and the matter's rate and staffing records. Ask whether the time entries, rates, narratives, and expenses satisfy every applicable rule. Flag any requirement that cannot be met with the current evidence. The check should happen early enough to change the packet, not after the partner has approved it.","Keep a short list of known conflict types so reviewers know what to look for: effective-date conflicts, entity-specific rules, rate caps versus quoted rates, staffing restrictions, and narrative format clashes. A checklist that names the common conflicts is faster to use than a general instruction to read the guidelines. Update the list when a new conflict appears. Review the list at each guideline update so it stays aligned with the client's current requirements."]},{"heading":"Decide the interim rule and who owns it","paragraphs":["For the current invoice, choose the rule that is most defensible and least likely to harm the client relationship. Often that means following the stricter client requirement and documenting why the other rule was not applied. The decision should be made by the relationship owner or the billing manager, not by the assistant alone. Record the interim rule and the rationale in the prebill file.","If the amount at risk is material, escalate before release rather than after the client objects. The escalation should include the conflicting sources, the interim decision, and the question that needs an answer. A clear ask is easier to resolve than a general concern. The goal is a documented decision, not a perfect one."]},{"heading":"Ask the client one precise question","paragraphs":["When the conflict requires client input, ask one precise question that names the two rules and the practical choice. For example, ask whether the client wants daily entries consolidated into the monthly invoice or submitted through the portal each day. Include the relevant guideline sections and the date the answer is needed. A vague request for clarification often produces a vague answer.","Route the question through the relationship owner or the agreed client contact, not through an unrelated billing mailbox. Keep the tone factual and focused on how to submit correctly. Record the response and the date in the guideline file. If the client does not answer in time, apply the interim rule and tell the client what was done."]},{"heading":"Record the resolution and its scope","paragraphs":["Write down the resolution, the source of the answer, and the matters or periods it covers. Distinguish a one-time exception from a change to the standing guideline. If the client grants an exception, note its expiration and the person who approved it. A resolution that is not scoped will be applied too broadly or forgotten too quickly.","Update the guideline summary and the prebill checklist with the resolved rule. If the conflict changed a field or a review step, note the change in the change log. The next reviewer should not have to rediscover the same conflict. The record is the bridge between the current invoice and the next one."]},{"heading":"Keep the prebill moving without hiding risk","paragraphs":["A conflict does not always justify holding the entire invoice. If the affected lines are a small part of the packet, release the unaffected work and hold only the disputed portion with a clear note. That approach protects cash flow and gives the client a specific issue to resolve. The key is to make the partial release visible, not to bury the exception in a footnote.","If the whole invoice depends on the answer, set a decision deadline and a fallback. Tell the partner and the client what will happen if the answer does not arrive. A fallback might be submitting under the stricter rule with a covering note. The team should never be in a position where the only option is an unexplained delay."]},{"heading":"Update the guideline summary and checklist","paragraphs":["After the conflict is resolved, revise the summary so the rule is stated in one place and the old wording is removed or marked superseded. Add the conflict to the checklist if it is likely to recur. Tell the reviewers what changed and why. A summary that accumulates contradictory notes is worse than no summary because it forces each reviewer to interpret the history.","Keep the source document, the resolution note, and the updated summary linked together. The link lets a future reviewer verify the rule without reopening the whole email thread. Review the summary at the next guideline update to confirm it still matches the client's current position. The record should be easy to maintain, not a second project."]},{"heading":"Review conflicts for patterns","paragraphs":["Each quarter, count the conflicts by client, rule type, and matter. A conflict that appears once may be an anomaly, while a repeated conflict points to an unclear guideline or a training gap. Share the pattern with the relationship owner and the billing team. The goal is to reduce the number of future conflicts, not just to resolve them faster.","Use the pattern to decide whether to ask the client for a clearer guideline, change the firm's intake summary, or add a review step. Record the decision and the owner. A conflict log that is never reviewed becomes another archive. The review turns it into a feedback loop that improves the next prebill."]}],"faq":[{"q":"What counts as a billing guideline conflict?","a":"A conflict exists when two client requirements cannot both be met, or when a client rule contradicts the firm's policy or a documented partner instruction. Record both sources before deciding how to proceed."},{"q":"Can the billing assistant resolve the conflict alone?","a":"The assistant can detect the conflict, gather the sources, and prepare the options. The relationship owner or billing manager should make the interim decision and approve any client communication. The assistant should not choose which client rule to ignore."},{"q":"What if the client does not respond before the deadline?","a":"Apply the documented interim rule, usually the stricter requirement, and tell the client what was done and why. Record the unanswered question and follow up after submission. Do not hold the invoice indefinitely without a decision deadline."}],"publishedAt":"2026-11-08"},{"slug":"write-a-collections-escalation-ladder-that-preserves-the-client-relationship","title":"Write a collections escalation ladder that preserves the client relationship","description":"A staged collections ladder with clear timing, message templates, authority limits, and pause rules that protect both cash flow and the client relationship.","category":"Collections","readTime":"8 min read","thumbnail":"/thumbnails/november-08/write-a-collections-escalation-ladder-that-preserves-the-client-relationship.webp","internalService":"/services/invoice-follow-up","internalSibling":"/blog/run-a-daily-e-billing-status-reconciliation","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Why an escalation ladder beats a reminder cycle","paragraphs":["A reminder cycle repeats the same message at the same tone until someone eventually answers or gives up. An escalation ladder defines what happens at each stage, who owns it, and what the client should expect. The difference is not aggression; it is predictability. Clients respond better when the process is clear and the requests are specific.","The ladder also protects the firm from inconsistent pressure. One partner may avoid follow-up for months while another calls immediately, and the client experiences the firm as unpredictable. A written ladder gives everyone the same sequence and the same evidence standard. It makes collections a managed process rather than a personality-driven one."]},{"heading":"Define the stages and the timing","paragraphs":["Start with the invoice due date and define the first follow-up, the second follow-up, the partner call, and the formal escalation. Set the timing in business days and align it with the client's payment terms and the firm's cash flow needs. A typical ladder might begin a few days after the due date and escalate over several weeks. The exact intervals should reflect the client relationship, not a generic template.","Name the owner for each stage and the evidence required to move to the next one. The first stage may be an automated reminder, while the partner call requires a prepared account summary. Do not let a stage be skipped because someone is impatient, and do not let it stall because the owner is unavailable. A backup owner should be named for every stage."]},{"heading":"Write the message for each stage","paragraphs":["Each message should state the invoice number, the amount, the due date, and the specific action requested. Keep the tone professional and assume good faith until the evidence says otherwise. Include a direct contact and a clear next step, such as a payment date or a call to discuss. Avoid vague language that invites another round of delay.","Later stages should reference the earlier communication without becoming a threat. A short factual history helps the client understand why the firm is escalating. If the client has promised payment, acknowledge the promise and ask for a confirmation date. The message should make it easy to resolve the issue, not just harder to ignore it."]},{"heading":"Keep the evidence ready before the first call","paragraphs":["Before the first personal follow-up, assemble the invoice, the client's payment history, the engagement terms, and any prior promises or disputes. The caller should not have to search for basic facts during the conversation. A one-page account summary with the key dates and amounts is enough for most calls. The evidence should be current and linked to the billing system.","Record the outcome of every call in the same place as the invoice. Note who spoke, what was promised, and the date of the next action. If the client disputes a charge, capture the specific issue and route it to the billing owner. An undocumented call is not a collections record, and it cannot support the next stage."]},{"heading":"Set authority limits for holds and promises","paragraphs":["Decide who can approve a payment plan, a short hold, a partial payment, or a write-off. Write the limits by amount and by client sensitivity so the team does not have to guess. An assistant can offer a standard option within the limit but should escalate anything outside it. The client should receive a consistent answer regardless of who takes the call.","Record every promise and every concession with the approver and the expiration date. A hold that is granted verbally without a date becomes an indefinite delay. Review open promises weekly and follow up before they expire. Authority limits protect the firm and make the team more confident in the conversation."]},{"heading":"Pause the ladder when a dispute is open","paragraphs":["If the client disputes the invoice or a specific charge, pause the collections ladder while the dispute is reviewed. Send a written acknowledgement that names the issue and the expected response time. Do not continue sending payment reminders during an active dispute, because it damages trust and complicates the resolution. The pause should be recorded in the account history.","Set a review date and an owner for the dispute. If the dispute is not resolved by that date, escalate internally rather than resuming the ladder automatically. Once resolved, restart at the appropriate stage based on the revised amount and terms. A clear pause and restart rule prevents both premature pressure and indefinite drift."]},{"heading":"Protect the relationship during firm escalation","paragraphs":["At the later stages, involve the relationship partner or the client service lead before any formal legal or agency step. The person who knows the client should decide whether a call, a meeting, or a written notice is appropriate. Keep the message focused on the outstanding amount and the path to resolution. Avoid language that questions the client's integrity.","If the firm must take a formal step, document the decision and the client communication that preceded it. Give the client a final opportunity to respond with a specific deadline. The goal is to collect what is owed while preserving the possibility of future work. A collections process that burns the relationship is a costly win."]},{"heading":"Review the ladder with finance and the relationship owner","paragraphs":["Review the ladder quarterly with finance, the billing manager, and a relationship owner. Look at the accounts that escalated, the time to payment, and the disputes that paused the process. Ask whether the timing and tone matched the client's behavior and the firm's risk. Adjust one stage at a time and observe the effect.","Update the templates and authority limits when the review shows a gap. Share a short summary with the team so everyone knows what changed. The ladder should be a living document, not a policy that sits in a folder. A process that is reviewed and simplified is more likely to be followed under pressure."]}],"faq":[{"q":"How soon should collections start after the due date?","a":"Start with a polite reminder a few business days after the due date, then escalate at intervals that fit the client relationship and the firm's cash flow. The timing should be written down and applied consistently."},{"q":"Can a billing assistant make collection calls?","a":"An assistant can prepare the account summary, send standard reminders, and record outcomes. Calls that involve concessions, disputes, or relationship risk should be handled by the named owner within the authority limits."},{"q":"What should happen when a client disputes an invoice?","a":"Pause the ladder, acknowledge the dispute in writing, assign an owner, and set a response date. Resume only after the dispute is resolved and the revised amount is documented."}],"publishedAt":"2026-11-08"}];

export const november08ResearchPosts: readonly ResearchPost[] = [{"slug":"how-much-billing-rework-comes-from-unclear-partner-instructions","title":"How much billing rework comes from unclear partner instructions?","summary":"A study protocol for measuring rework caused by ambiguous partner instructions, including definitions, sampling, coding, and reporting limits.","cluster":"Billing operations","finding":"Instruction-driven rework is measurable when each correction is tied to the original instruction, the missing detail, and the staff time required to resolve it.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much billing rework is caused by partner instructions that lack a needed detail. The unit is a rework event, meaning a billing task that had to be repeated, corrected, or escalated because the original instruction was unclear. The purpose is to distinguish an instruction problem from a rate, guideline, or system problem. The result is an operational estimate, not an evaluation of any partner's communication style.","Scope the study to one billing team and a defined period, such as one quarter or two billing cycles. Include instructions delivered in person, by email, by message, or through a task system. Exclude work that was redone because the client changed a requirement after the instruction was given. State the team, the matters, and the instruction channels included so the estimate is not applied outside its scope."]},{"heading":"Defining an unclear instruction","paragraphs":["An instruction is unclear when a reasonable billing specialist cannot complete the requested action without asking a follow-up question or making an assumption that later proves wrong. The ambiguity may concern scope, amount, rate, narrative, timing, or approval authority. Record the specific missing element rather than labeling the whole instruction as vague. A precise definition makes the coding repeatable.","Distinguish an unclear instruction from an incomplete record. If the partner gave a clear direction but the supporting document was missing, that is a records problem. If the partner said to make the invoice reasonable without naming the amount or standard, that is an instruction problem. The two can occur together, so record the primary cause and any secondary cause separately."]},{"heading":"Rework events and the unit of analysis","paragraphs":["Count one rework event each time the original task must be revisited because of the instruction gap. A single instruction may generate several events if it affects multiple invoices or timekeepers. Record the event at the point of correction, not at the end of the month when the memory has faded. The event should have a start time, an end time, and a clear description of the repeated work.","Use the billing task as the primary unit and the matter as a secondary unit. The task-level view shows where the time goes, while the matter-level view shows whether the problem concentrates in particular engagements. Report both so a leader can see the operational cost and the relationship context. Do not average across dissimilar task types without showing the mix."]},{"heading":"Evidence sources","paragraphs":["Use the original instruction, the follow-up question, the corrected task, and the final approval as the core evidence. The follow-up question is often the clearest proof that a detail was missing. If the correction happened without a question, record the assumption that was made and how it was discovered. Link each source to the rework event so a second reviewer can verify it.","Add the billing system timestamps and the queue history where available. These records show when the task was opened, changed, and closed. Do not rely on a recollection that the instruction was confusing. The evidence standard should let an analyst confirm the event from the file without interviewing the people involved."]},{"heading":"Sampling and observation","paragraphs":["If the volume is manageable, review every rework event in the period. If not, sample by partner, matter type, and instruction channel so the sample reflects the population. Draw the sample before reviewing outcomes to avoid selecting only the most dramatic cases. Record the sampling frame and the inclusion rules in the study file.","Ask the billing specialists to log potential events during the period using a short form. The form should capture the instruction, the missing detail, the action taken, and the time spent. Keep the form short enough that people complete it in the moment. A long form produces late, reconstructed entries that are less reliable."]},{"heading":"Coding the cause","paragraphs":["Use a small cause list: missing amount, missing scope, missing rate basis, missing narrative standard, missing approval, conflicting instruction, and other. Define each code with an example and an exclusion. Add a secondary code when more than one detail was missing. The coding should point to a specific fix, such as a template field or a confirmation step.","Have a second reviewer code a sample and compare the results. Report the agreement rate and resolve disagreements by returning to the evidence. If a code cannot be applied consistently, revise the definition before continuing. The coding scheme is part of the measurement, not an afterthought."]},{"heading":"Measuring time and cost","paragraphs":["Measure active time per rework event, not elapsed time. Active time includes rereading the instruction, asking the question, rebuilding the task, and rechecking the result. Waiting for a response is a separate measure because it affects cycle time but not staff effort. Report both so the team can see the difference between a slow answer and a costly correction.","Multiply the observed time by the number of events to estimate total effort for the period. Report the median and the range rather than a single average, because a few complex events can distort the mean. Do not convert time to a dollar cost unless the firm provides an approved labor rate and the method for applying it. The protocol measures effort, not price."]},{"heading":"Analysis and reporting","paragraphs":["Report the number of rework events, the share of instructions affected, and the active time per event. Break the results down by cause, partner group, matter type, and instruction channel. A high rate in one channel may point to a template or a meeting habit rather than an individual. Show the count behind each rate so a small sample is visible.","Compare the cost of the rework with the cost of the prevention step. A short confirmation template may prevent several events at a low cost, while a new meeting may add time without solving the cause. Report both sides of the comparison. The output should identify one or two specific changes, not just a ranking of causes."]},{"heading":"Limits and sources of error","paragraphs":["Self-reported logs can be incomplete or rounded, and people may underreport events that felt routine. Pair the log with a sample of direct observation or system timestamps to check for bias. Report the share of events with estimated time. A precise number based on coarse logs is misleading.","The study may overrepresent partners who give many instructions or matters with heavy billing activity. Report the mix and avoid comparing partners on a raw count without adjusting for volume. The purpose is to improve the instruction process, not to rank individuals. Keep the limitations beside the result."]},{"heading":"Retention and privacy","paragraphs":["Store the instruction evidence and the time logs in a controlled billing folder. Remove client names and matter numbers from the analysis file when they are not needed. If an example is used in training, redact the client and the individual partner. Follow the firm's records policy for the retention period.","Limit access to the study team and the billing manager. Do not circulate a list of partners with the highest rework counts outside the management context. The study is about process design, not personal performance. Aggregate the results before sharing them more broadly."]},{"heading":"Applying the result","paragraphs":["If missing amounts dominate, add an amount field to the standard instruction template. If missing scope dominates, require the matter and phase to be named before the task is accepted. If conflicting instructions dominate, add a confirmation step that resolves the conflict before work begins. The fix should match the most common cause.","Test the change on a small sample in the next cycle and compare the event rate with the baseline. A drop in one cause with no increase in another is evidence that the change worked. If the rate does not move, examine whether the instruction channel or the matter mix changed. Record the result and set the next review date."]},{"heading":"Review cadence","paragraphs":["Repeat the study each quarter while instruction templates are being changed, then move to a semiannual cycle. Keep the cause definitions and the event rule stable so the trend is comparable. Report any change in the instruction channels or the matter mix beside the result. A measure that changes its method every cycle cannot show whether the process improved.","Review the findings with the billing manager and a partner group that gives many instructions. Ask which missing detail causes the most rework and which template change is practical. Set one change and a follow-up date before the next cycle. The review should end with a named owner, not a general agreement that communication matters."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/how-much-billing-rework-comes-from-unclear-partner-instructions.webp"},{"slug":"what-share-of-client-billing-questions-arrive-after-the-due-date","title":"What share of client billing questions arrive after the due date?","summary":"A timing study for client billing questions that separates pre-due clarification from post-due disputes and reports the operational effect.","cluster":"Invoice follow-up","finding":"The timing of client questions is a measurable service signal, and the share arriving after the due date should be reported by question type and client rather than as one percentage.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of client billing questions arrive after the invoice due date. The unit is a question event, defined as a client communication that requires a billing response before the invoice can be considered resolved. The purpose is to understand whether the firm is inviting questions early enough or learning about problems only when payment is late. The result describes timing, not the merits of any question.","Scope the study to invoices issued in a defined period and to questions received through the agreed client channels. Include email, portal messages, calls logged by the billing team, and formal dispute notices. Exclude internal questions from partners and routine payment confirmations. State the period, the clients, and the channels included so the result is comparable."]},{"heading":"Defining a billing question","paragraphs":["A billing question is a client request for explanation, correction, or supporting detail about an invoice or a charge. A payment confirmation is not a question, and a simple acknowledgement is not a question. A dispute is a question with a stated disagreement, and it should be coded separately. The definition should require a response from the billing team, not just a read receipt.","Distinguish a question about the invoice from a question about the matter or the legal work. A client may ask why a case took a certain course, which belongs to the relationship owner rather than the billing queue. Record the subject so the analysis does not mix billing process issues with legal service issues. The billing team can still coordinate the response without owning the substance."]},{"heading":"Population and denominator","paragraphs":["The population is every invoice issued in the period that reached the client through an active channel. Exclude invoices that were never sent, were cancelled before delivery, or were replaced by a credit memo before the client saw them. Report the number of invoices and the number of questions so the reader can see the base. A question rate without a denominator is not interpretable.","Use the invoice due date as the reference point and calculate the days between delivery, question, and due date. A question that arrives on the due date should be coded consistently, either as on-time or post-due, according to a written rule. Record the time zone used for the timestamps. Small timing choices can change the result when many questions arrive near the deadline."]},{"heading":"Data sources","paragraphs":["Use the billing system for invoice delivery and due dates, the shared inbox for question timestamps, and the portal for client messages. Reconcile the sources so the same question is not counted twice. If a question arrives by phone, record the call time and the person who took it. A missing timestamp should be marked, not guessed.","Link each question to the invoice and the client account. That link allows the analysis to separate questions about a specific charge from questions about the account or the payment process. Record the question type and the final resolution where available. The evidence should let a second analyst reproduce the count."]},{"heading":"Sampling","paragraphs":["If the invoice volume is large, sample by client, invoice amount, and delivery month. Include invoices with no questions so the denominator reflects the full population. Draw the sample before reviewing the question timing to avoid selecting only late disputes. Report the sampling method and the number of invoices drawn from each stratum.","For a smaller firm, review every invoice in the period and every logged question. Extend the period rather than lowering the evidence standard if the volume is too small. Track questions that arrive after the study window and report them separately. Dropping late-arriving questions would bias the result toward the early side."]},{"heading":"Timing analysis","paragraphs":["Report the share of questions arriving before the due date, on the due date, and after the due date. Add the median number of days after delivery and the median days before or after the due date. A single share hides whether late questions arrive one day late or several weeks late. The distribution is more useful than the average.","Break the timing down by question type. A rate question may arrive early because the client reviews the invoice immediately, while a narrative dispute may arrive late after an internal audit. Compare the pattern across clients only when the delivery method and payment terms are similar. Note any client-specific review cycle that explains the difference."]},{"heading":"Coding question types","paragraphs":["Use codes such as rate, narrative, staffing, expense, duplicate charge, budget, payment terms, and other. Define each code with an example and require a short note for the other category. A question can have more than one code, so name the primary code and list secondary codes. The coding should point to the invoice field or process that needs attention.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the client message and the invoice. If a code is used inconsistently, revise the definition before continuing. The code list should be short enough to remember and specific enough to guide a fix."]},{"heading":"Reporting","paragraphs":["Report the overall share, the distribution by timing, and the breakdown by question type and client. Include the number of invoices and questions behind each rate. Show the share of questions that required a credit or write-down, because a late question with no financial effect is different from one that changes the invoice. The report should separate frequency from consequence.","Present the results to the billing manager and the relationship owners with a short note on what the timing suggests. If most questions arrive after the due date, the issue may be invoice clarity, delivery timing, or the client's review process. The report should propose one test, not a general conclusion. Keep the raw data available for a follow-up review."]},{"heading":"Limits and sources of error","paragraphs":["Clients may ask questions through channels the firm does not capture, such as a direct call to a partner. Those questions can be missing from the study and make the late share look lower. Ask the relationship owners whether they received billing questions outside the tracked channels. Report the estimated gap rather than assuming the record is complete.","Payment terms and invoice delivery dates vary by client, so a raw comparison can be misleading. Report the terms beside the timing result and avoid ranking clients on late questions alone. The study measures when questions arrive, not whether the client is difficult. Keep the limitations beside the conclusion."]},{"heading":"Privacy and retention","paragraphs":["Store the question log and the invoice links in a controlled billing folder. Remove client names and matter details from the analysis file when they are not needed. If an example is shared for training, redact the client and the amounts. Follow the firm's records policy for the retention period.","Limit access to the study team and the billing manager. Do not circulate a client-level list outside the group that needs it for service improvement. Aggregate the results before sharing them more broadly. The same privacy rule applies to any screenshots of portal messages."]},{"heading":"Applying the result","paragraphs":["If many questions concern narratives, test a clearer invoice summary or a short pre-submission note that explains the narrative standard. If rate questions dominate, review the rate display and the client's rate history. If questions arrive late because the client reviews internally, ask whether an earlier draft or a summary call would help. The fix should match the question type and the timing.","Test one change on a defined client group and compare the timing distribution with the baseline. A shift from post-due to pre-due questions is a service improvement even if the total number stays the same. Record the result and the next review date. The study should improve the conversation around invoices, not just measure it."]},{"heading":"Review cadence","paragraphs":["Repeat the study quarterly for the first year after an invoice format or delivery change, then twice a year. Keep the question definition and the due-date rule stable so the timing comparison is valid. If a client changes payment terms, report that client separately rather than blending it into the total. A stable method is what makes a trend trustworthy.","Review the results with the billing manager and the relationship owners for the clients in the sample. Ask which questions could have been prevented by a clearer invoice or an earlier conversation. Choose one client group for a test and set a follow-up date. The review should connect the timing data to a specific service change."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/what-share-of-client-billing-questions-arrive-after-the-due-date.webp"},{"slug":"how-often-do-matter-budgets-change-after-the-first-prebill","title":"How often do matter budgets change after the first prebill?","summary":"A budget revision study that counts changes after the first prebill, codes the reasons, and reports the effect on client communication and approval.","cluster":"Budgets","finding":"Budget changes are a normal part of active matters, but the rate and timing of revisions should be measured separately from the quality of the original estimate.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often a matter budget changes after the first prebill is prepared. The unit is a budget revision event, defined as a change to the approved amount, phase allocation, or staffing plan that is recorded after the first prebill. The purpose is to understand how stable the budget is during the billing cycle and whether clients are informed before the change appears on an invoice. The result describes the process, not the accuracy of any individual estimate.","Scope the study to matters with a written budget and at least one prebill in the period. Include revisions requested by the client, the partner, or the billing team. Exclude routine accrual updates that do not change the approved budget. State the matter types, the clients, and the period included so the result is not generalized beyond the sample."]},{"heading":"Defining a budget change","paragraphs":["A budget change occurs when the total approved amount, the phase allocation, or the staffing plan changes in a way that affects the client's expectation or the firm's approval. A change from one timekeeper to another may be a staffing change even if the total stays the same. Record the type of change and the date it was approved. The definition should match the fields the firm actually maintains.","Distinguish a formal revision from a forecast update. A formal revision changes the approved budget and usually requires client communication or internal approval. A forecast update changes the expected spend without changing the approved amount. Both are useful, but they answer different questions. Report them separately so a routine forecast does not look like a budget breach."]},{"heading":"Baseline and revision records","paragraphs":["Capture the baseline budget, the approval date, and the source document before the first prebill. Record the phase amounts and the assumptions that matter for the work. If the baseline is only a total number, note that limitation because it prevents a phase-level analysis. A baseline without a date cannot support a timing comparison.","For each revision, record the prior amount, the new amount, the reason, the approver, and the client communication date. Link the revision to the prebill or invoice that triggered it. If the revision was discussed verbally, record the date and the participants. The record should let a reviewer reconstruct the sequence without guessing."]},{"heading":"Sampling","paragraphs":["Sample matters across practice areas, matter sizes, and clients with different budget requirements. Include matters with no revisions so the denominator reflects the full population. Draw the sample before reviewing the revision history to avoid selecting only the most volatile matters. Report the sampling frame and the number of matters in each stratum.","If the firm has few budgeted matters, extend the period rather than reducing the evidence standard. Track matters that close during the window and matters that remain open at the end. Report open matters separately because their revision history is still developing. Dropping them would bias the result toward shorter matters."]},{"heading":"Data collection","paragraphs":["Use the budget record, the prebill history, the matter management system, and client correspondence as the primary sources. Record the date each revision was approved and the date the client was told. The gap between the two is a useful measure of communication lag. If the client was never told, mark that as a missing communication rather than assuming it happened.","Collect the data at defined milestones: first prebill, mid-matter review, and closing. A single end-of-matter review may miss revisions that were later reversed. The milestone approach captures the state the reviewer actually saw. Keep the collection dates so the timeline is clear."]},{"heading":"Coding the reasons","paragraphs":["Use codes such as scope change, staffing change, rate change, client request, estimate error, and other. Define each code with an example and require a note for the other category. Add a secondary code when more than one reason applies. The coding should point to a specific prevention or communication step.","Distinguish a revision caused by new information from one caused by an error in the original estimate. A scope change is often legitimate and predictable, while an estimate error may point to a template or review gap. Report the two separately so the firm does not treat every revision as a failure. The cause should be based on evidence, not on alater recollection."]},{"heading":"Analysis","paragraphs":["Report the share of matters with at least one revision, the median number of revisions, and the median time from the first prebill to the first revision. Include the share of revisions communicated to the client before the next invoice. A revision that is approved internally but never communicated creates a client surprise even if the number is correct. Report the count of matters behind each share so a small sample is visible.","Break the results down by matter type, client, and reason. A high revision rate in one practice area may reflect the nature of the work, while a high rate in another may reflect a weak intake estimate. Compare only matters with similar scope and duration. The analysis should describe the pattern, not rank the partners."]},{"heading":"Reporting","paragraphs":["Report the revision rate, the timing, the reasons, and the communication lag together. A high rate with early client communication is a different problem from a low rate with late communication. Show the number of matters behind each rate. The report should make the operational trade-off visible.","Present the results to the billing manager, the budget owner, and a relationship partner. Ask which revisions were avoidable and which were legitimate. Set one change to the intake estimate or the client communication routine. The report should lead to a decision, not just a description."]},{"heading":"Limits and sources of error","paragraphs":["Budget records are often incomplete, especially when the original estimate was verbal or stored in a separate spreadsheet. A missing revision is not proof that no change occurred. Report the completeness of the source before drawing conclusions. Name the owner of the budget record and the system where it is maintained.","Matter duration and scope complexity confound comparisons across practice areas. A long matter has more opportunity for revision, and a fixed-fee matter may have no budget revisions at all. Report the context beside the rate and avoid comparing unlike matters. The purpose is to improve the process, not to judge the estimate in isolation."]},{"heading":"Privacy and retention","paragraphs":["Store the budget history in the controlled matter record and keep the study file separate from the live budget. Remove client names and matter details from the analysis file when they are not needed. If an example is shared, use a role label and a rounded amount. Follow the firm's records policy for the retention period.","Limit access to the study team and the budget owner. Do not circulate a partner-level revision list outside the management context. Aggregate the results before sharing them more broadly. The same care applies to client communications quoted in the study."]},{"heading":"Applying the result","paragraphs":["If estimate errors dominate, add a phase-level check to the intake budget and a second review before the first prebill. If scope changes dominate, build a client communication step into the change approval. If communication lag dominates, add the client notice date to the revision record and review it weekly. The fix should match the most common reason.","Test the change on a defined group of matters and compare the revision rate and communication lag with the baseline. A lower rate of avoidable revisions is the direct result, while earlier client notice is the service result. Report both. Set a follow-up date and keep the definitions stable so the comparison is valid."]},{"heading":"Review cadence","paragraphs":["Repeat the study annually and after a major rate change, practice group reorganization, or budget template revision. Keep the baseline and revision definitions stable so the comparison is meaningful. Report the matters that crossed a material threshold separately from routine forecast updates. A change in the client mix should be noted beside the rate.","Review the findings with the budget owner, the billing manager, and a relationship partner. Ask which revisions were avoidable and which communication step would have helped the client most. Set one change and a follow-up date. The next study should test whether that change reduced avoidable revisions without hiding legitimate scope changes."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/how-often-do-matter-budgets-change-after-the-first-prebill.webp"},{"slug":"where-do-billing-setup-errors-originate-in-new-matter-intake","title":"Where do billing setup errors originate in new matter intake?","summary":"An origin study for billing setup errors that traces each missing field to the intake step, the source record, and the person who could have caught it.","cluster":"Matter records","finding":"Setup errors are best understood by origin step rather than by error type, because the origin determines whether the fix belongs to intake, billing, or the client relationship owner.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks where billing setup errors originate in the new matter intake process. The unit is a setup error, defined as a missing or incorrect billing field discovered after the matter is opened. The purpose is to find the step where the error could have been prevented, not to assign blame to the person who happened to open the matter. The result should point to a specific intake control.","Scope the study to matters opened in a defined period and to the billing fields the firm requires at intake. Include rates, client guidelines, billing contacts, e-billing enrollment, matter identifiers, budgets, and trust arrangements. Exclude errors caused by a later client change unless the change was known at intake. State the matter types and the intake channels included."]},{"heading":"Defining a setup error","paragraphs":["A setup error exists when a required billing field is missing, inconsistent with the source document, or attached to the wrong matter. The error must be discoverable from a source record, not just from a disagreement between people. Record the field, the expected value, the actual value, and the source that proves the expectation. A field that was never required is not an error.","Distinguish a setup error from a data entry typo that has no billing effect. A wrong phone number in a contact field may be minor, while a wrong billing entity can delay an entire invoice. Classify errors by their operational consequence as well as their origin. The consequence helps the firm decide which fixes matter most."]},{"heading":"Intake stages","paragraphs":["Map the intake process into stages: client request, conflicts and engagement, matter opening, billing setup, e-billing enrollment, and first prebill. Assign each required field to the stage where it should be captured. A field with no assigned stage is a design gap, not a training problem. The map becomes the frame for coding the origin.","Include the handoffs between stages, because many errors occur when a field is known in one conversation but not transferred to the system. Record who owns each handoff and what evidence confirms the transfer. The intake map should be simple enough to compare across matters. If the process varies by practice group, map the variation explicitly."]},{"heading":"Evidence sources","paragraphs":["Use the engagement letter, the client guideline document, the rate card, the e-billing enrollment record, and the matter opening form as primary evidence. Compare the source with the field in the billing system. Record the date the source was received and the date the field was entered. The gap between the two is part of the error history.","If the source was a conversation, record the date, the participants, and the note that captured the instruction. A missing source is itself a finding, because it means the field cannot be verified. Do not treat a field as correct just because no one has complained. The evidence standard should be the same for every matter in the sample."]},{"heading":"Sampling","paragraphs":["Sample matters across practice groups, intake channels, and matter sizes. Include matters opened by different staff members so the sample is not concentrated in one person's work. Draw the sample before reviewing the errors to avoid selecting only the matters known to be problematic. Record the sampling frame and the number of matters in each stratum.","For a small firm, review every matter opened in the period. Extend the period rather than reducing the evidence standard. Track matters that were still being set up at the end of the window and report them separately. A matter that has not reached first prebill may not yet reveal its errors."]},{"heading":"Coding the origin","paragraphs":["Code the stage where the field should have been captured, the stage where it was actually captured, and the stage where the error was discovered. Use a short list of stages and a separate code for no assigned stage. The three-part code shows whether the problem is a missing step, a skipped step, or a late detection. That distinction is more useful than a single label.","Add a cause code for the mechanism, such as source not received, source not read, field not available, handoff missed, or system limitation. Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the evidence. If the codes are too broad, split the one that causes the most disagreement."]},{"heading":"Analysis","paragraphs":["Report the error rate by field, origin stage, and matter type. Identify the fields with the highest error rate and the stages where the most errors should have been caught. A field that is consistently missing at the same stage points to a process design issue. A field that is entered correctly but later overwritten points to a system or handoff issue.","Calculate the share of errors discovered at first prebill, because late discovery is the most expensive. Compare the error rate for matters opened with a checklist against those opened without one. Report the count behind each rate. The analysis should show where a control would have the greatest effect."]},{"heading":"Reporting","paragraphs":["Report the overall setup error rate, the field-level results, and the origin-stage results. Include the share of errors that reached the first prebill and the share that caused a client-facing delay. Show the number of matters in the sample. The report should separate frequency from consequence.","Present the findings to the intake owner, the billing manager, and the practice group lead. Ask which stage is easiest to change and which error causes the most rework. Set one control change and a follow-up date. A report that does not lead to a change is just another audit."]},{"heading":"Limits and sources of error","paragraphs":["The source documents may be incomplete, especially when a client provides information in a call or a meeting. A missing source does not prove that the field was never known. Report the completeness of the evidence before drawing conclusions. Name the owner of each source and the system where it should be stored.","Matters differ in complexity and client requirements, so a raw error rate can reflect the mix rather than the process. Report the context beside the rate and avoid comparing practice groups without adjusting for scope. The study is about intake design, not individual performance. Keep the limitations visible."]},{"heading":"Privacy and retention","paragraphs":["Store the sample and the source evidence in a controlled folder. Remove client names and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client. Follow the firm's records policy for the retention period.","Limit access to the study team and the intake owner. Do not circulate a list of errors by staff member outside the management context. Aggregate the results before sharing them more broadly. The same privacy rule applies to any screenshots of the matter system."]},{"heading":"Applying the result","paragraphs":["If most errors originate at matter opening, add the missing fields to the opening form and require a source link for each. If they originate at the handoff to billing, add a confirmation step with a named owner. If they are discovered only at prebill, add a setup check before the first time entry. The fix should match the origin stage.","Test the change on the next group of matters and compare the error rate and the late-discovery share with the baseline. A lower late-discovery share is the most valuable result because it prevents client-facing delays. Record the result and set a review date. The intake process should improve with each cycle."]},{"heading":"Review cadence","paragraphs":["Repeat the study before each intake form change and at least annually. Keep the stage map and the error definition stable so the origin comparison remains valid. If a practice group changes its intake process, map that variation before combining the results. A current stage map is essential for interpreting where the errors originate.","Review the findings with the intake owner, the billing manager, and the practice group lead. Ask which stage is easiest to change and which error causes the most client-facing delay. Set one control change and a follow-up date. The next review should check whether late discovery fell, not just whether the total error count moved."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/where-do-billing-setup-errors-originate-in-new-matter-intake.webp"},{"slug":"how-much-shared-billing-inbox-time-goes-to-duplicate-messages","title":"How much shared billing inbox time goes to duplicate messages?","summary":"A duplicate-message study that measures the staff time spent reading, routing, and answering the same billing request more than once.","cluster":"Invoice follow-up","finding":"Duplicate inbox effort is measurable when each duplicate is linked to an original message and the time spent on the duplicate is logged separately from the time spent on the underlying request.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much staff time in a shared billing inbox is spent on duplicate messages. The unit is a duplicate-handling event, defined as the time spent reading, routing, or responding to a message that repeats a request already present in another message. The purpose is to quantify a hidden cost that rarely appears in a service report. The result should help the team decide whether to fix intake, search, or assignment.","Scope the study to one shared billing inbox and a defined period. Include duplicates created by client resends, internal forwards, automated notifications, and portal copies. Exclude a new message that adds material information even if it references the same invoice. State the inbox, the team, and the channels included so the result is not generalized to every queue."]},{"heading":"Defining a duplicate","paragraphs":["A duplicate is a message that requests the same action on the same invoice or matter as an earlier message, without adding a new fact or a new deadline. The request may be phrased differently or come from a different person at the same client. The test is whether the underlying work would be the same. Record the original message and the duplicate so the link is clear.","Distinguish a duplicate from a follow-up. A follow-up asks for status on a request that has not been answered, and it may be legitimate even when it repeats the subject. A duplicate creates a second handling path because the sender or the forwarding process did not connect it to the first. Code follow-ups separately so the study does not overstate the duplicate problem."]},{"heading":"Population and observation","paragraphs":["The population is every message received in the shared inbox during the period. The observation unit is the duplicate-handling event, not the message, because one duplicate can consume time in several people's queues. Record the message timestamp, the sender, the linked original, and the person who handled it. A message that is deleted without being read is not a handling event.","Observe the inbox at a consistent time each business day so the count is not skewed by a single busy morning. Record the inbox state, including unread messages and assigned items, at the start and end of the observation. If the inbox is too large to review fully, use a documented sample. The method should let a second analyst reproduce the count."]},{"heading":"Data sources","paragraphs":["Use the inbox metadata, the assignment history, and the linked queue records as the primary sources. The message headers show the timestamp and the sender, while the queue shows what work was created. If the team uses a separate ticketing tool, link the ticket to the message. A duplicate that exists only in a personal folder is outside the study.","Record the time spent on each duplicate event using a short log completed by the person who handled it. Include the time to read, search for the original, decide whether to merge, and respond. If the duplicate required a client reply, separate that time from the merge time. The breakdown shows whether the cost is in search, decision, or communication."]},{"heading":"Sampling","paragraphs":["If the inbox volume is manageable, review every message in the period. If not, sample by day, sender type, and subject category so the sample reflects the population. Include days with low volume as well as high volume. Draw the sample before reviewing the duplicate links to avoid selecting the most obvious cases.","For a small team, extend the period rather than reducing the evidence standard. Track messages that arrive at the end of the window and assign them to the next observation. Report the number of messages in the sample and the share of the total inbox volume. A duplicate rate without the denominator is not useful."]},{"heading":"Coding duplicates","paragraphs":["Use codes such as client resend, internal forward, portal copy, automated notice, and cc duplicate. Define each code with an example and a rule for the primary code when more than one applies. Add a code for unknown when the link cannot be established. The coding should point to the source of the duplication, not just the message content.","Have a second reviewer code a sample and compare the results. Resolve disagreements by reading both messages and the linked queue record. If a code is applied inconsistently, revise the definition. The coding scheme should be short enough to use during a busy inbox day."]},{"heading":"Measuring time","paragraphs":["Measure active time per duplicate event: reading, searching, deciding, merging, and replying. Keep search time separate because it is often the largest and most fixable component. Report the median and the range rather than a single average. A few complex duplicates can distort the mean.","Multiply the observed time by the number of duplicate events to estimate total effort for the period. Label the result as an estimate and show the uncertainty range from the sample. Do not convert the time to a dollar cost unless the firm provides an approved labor rate. The protocol measures effort, not price."]},{"heading":"Analysis and reporting","paragraphs":["Report the duplicate rate per hundred messages, the active time per event, and the share of time spent searching for the original. Break the results down by source code, sender type, and day of week. A high search share points to a search or labeling problem, while a high reply share points to an ownership problem. The breakdown is more actionable than the total.","Include the share of duplicates that were merged correctly and the share that produced a second response. A duplicate that consumes time but is merged into one answer is less risky than one that produces two different answers. Report both the cost and the consistency effect. The report should identify one process change and its owner."]},{"heading":"Limits and sources of error","paragraphs":["The study depends on the team's ability to identify the original message, and some links will be missed. Report the share of duplicates with an uncertain original. A high uncertain share means the inbox lacks enough structure for reliable measurement. Fix the search or labeling before drawing a firm conclusion.","Self-reported time can be rounded or incomplete, especially during busy periods. Pair the log with a sample of direct observation or system activity. Report the share of estimated time. The purpose is to understand the scale of the problem, not to produce a precise labor cost."]},{"heading":"Privacy and retention","paragraphs":["Store the message sample and the time logs in a controlled billing folder. Remove client names and matter details from the analysis file when they are not needed. If an example is used in training, redact the sender and the client. Follow the firm's records policy for the retention period.","Limit access to the study team and the inbox owner. Do not circulate a sender-level duplicate list outside the team that needs it. Aggregate the results before sharing them more broadly. The same rule applies to screenshots of the inbox."]},{"heading":"Applying the result","paragraphs":["If search time dominates, improve the subject convention and the matter reference in the inbox. If internal forwards dominate, add a rule that the forwarder must link the original thread. If portal copies dominate, route portal notices to a single queue with a clear owner. The fix should match the most common source.","Test the change on the same inbox and compare the duplicate rate and the search time with the baseline. A lower search time with the same duplicate count is still a gain in capacity. Record the result and set a review date. The inbox should become easier to read, not just faster to clear."]},{"heading":"Review cadence","paragraphs":["Repeat the study after any inbox change and quarterly during a template or routing rollout. Keep the duplicate definition and the time categories stable so the comparison is valid. Report search time separately from reply time, because the two point to different fixes. A change in inbox volume should be noted beside the rate.","Review the results with the inbox owner and the billing manager. Ask which duplicate source is easiest to remove and which one causes the most search time. Set one routing or labeling change and a follow-up date. The next study should test whether the change reduced handling time without pushing duplicates into private channels."]}],"sources":[{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/how-much-shared-billing-inbox-time-goes-to-duplicate-messages.webp"},{"slug":"what-share-of-write-off-requests-lack-a-documented-client-basis","title":"What share of write-off requests lack a documented client basis?","summary":"An evidence-completeness study for write-off requests that separates a client-driven adjustment from an internal quality decision.","cluster":"Write-offs","finding":"A write-off request should be scored on whether the client basis is documented, not only on whether the amount is approved, because an undocumented basis hides the real cause.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of write-off requests lack a documented client basis. The unit is a write-off request, defined as a formal request to reduce or remove a charge before or after invoicing. The purpose is to distinguish an adjustment supported by a client rule or communication from one supported only by an internal opinion. The result is an evidence-quality measure, not a judgment about whether the write-off was appropriate.","Scope the study to requests submitted in a defined period and to the records the firm maintains for each request. Include requests approved, rejected, and still pending. Exclude routine courtesy discounts that follow a published policy with no client-specific basis. State the approvers, the request types, and the period included so the result is comparable."]},{"heading":"Defining a documented client basis","paragraphs":["A documented client basis is a written client rule, guideline, contract term, or communication that supports the adjustment. The evidence should identify the client, the requirement, and the date it applied. A general statement that the client would not pay is not a documented basis unless it is tied to a specific client communication. The standard should be strict enough that a second reviewer can verify it.","Distinguish a client basis from an internal quality basis. A firm may write off a charge because a timekeeper made an error, even when the client never objected. That is a legitimate internal decision, but it should be coded separately. The study measures whether the stated basis is documented, not whether every write-off must be client-driven."]},{"heading":"Population and denominator","paragraphs":["The population is every write-off request submitted in the period, including those below the approval threshold if they are recorded. The denominator should count requests, not line items, unless the study is specifically about line-level adjustments. Report the total amount requested and the total approved so the reader can see the financial scale. A request count without amounts can understate the issue.","Exclude requests that were withdrawn before review or that were duplicates of an earlier request. Record the exclusion rule and the number excluded. If a request contains several unrelated adjustments, split it into separate units or state that it is treated as one. Consistency in the unit is essential for comparing rates."]},{"heading":"Evidence standard","paragraphs":["For each request, look for the source document, the date, the specific rule or statement, and the person who confirmed it. A link to a client guideline is stronger than a summary written by the requester. If the basis is a phone call, the evidence should include the date, the participants, and a note made at the time. A later recollection is weaker evidence and should be labeled as such.","Score the evidence as complete, partial, or missing. Complete means a reviewer could verify the basis without asking the requester. Partial means the basis is referenced but the source or scope is unclear. Missing means there is no client evidence at all. Define the three levels with examples so two reviewers apply the same standard."]},{"heading":"Sampling","paragraphs":["If the number of requests is small, review every one. If it is large, sample by amount, client, approver, and request type. Include both approved and rejected requests so the study does not reflect only the ones that passed. Draw the sample before reviewing the evidence to avoid selecting the most obvious gaps.","Report the sampling frame and the number of requests in each stratum. Track pending requests separately because their evidence may still be assembled. Do not drop them, since a pending request with no basis is a live risk. The sample should let the firm estimate the share of all requests with a complete basis."]},{"heading":"Coding completeness","paragraphs":["Code the primary evidence type: client guideline, client email, contract term, client call note, internal quality review, or none. Add a secondary code when more than one type applies. The primary code should point to the fix, such as a guideline summary or a call-note template. The coding should not reward a long narrative that lacks a source.","Have a second reviewer score a sample and compare the results. Resolve disagreements by reading the source and the request together. Report the agreement rate. If the reviewers cannot agree on what counts as complete, the standard is too vague and should be revised before continuing."]},{"heading":"Analysis","paragraphs":["Report the share of requests with complete, partial, and missing evidence. Break the results down by request type, amount band, and approver group. A high missing share for small requests may point to a threshold that skips documentation, while a high share for large requests is a more serious control gap. Show the count behind each rate.","Compare the evidence quality with the approval outcome. A request can be approved despite weak evidence if the approver knows the client, but that pattern should be visible. Report the share of approved requests with missing evidence. That measure shows where the control depends on individual knowledge rather than a record."]},{"heading":"Reporting","paragraphs":["Report the completeness rate, the amount represented, and the share of approved requests with missing evidence. Include examples of each evidence level, with client details removed. The report should let a reader see both the frequency and the financial exposure. Avoid presenting a single percentage without the categories behind it.","Present the findings to the billing manager, the finance approver, and a relationship partner. Ask which evidence type is easiest to require at submission and which gap causes the most rework. Set one change to the request template and a follow-up date. The report should improve the quality of the next request, not just describe the last one."]},{"heading":"Limits and sources of error","paragraphs":["The request file may not contain every client communication, especially when the basis was discussed in a meeting. A missing document is not proof that no basis exists, but it is still a documentation gap. Report the share of requests where the reviewer had to ask for evidence. That share is a useful signal of how often the file is incomplete.","Approvers may apply judgment that is not captured in the request, so the study can understate the evidence available in practice. Interview a small sample of approvers to understand what they relied on. Label that information as supplemental rather than treating it as a written basis. The study measures the record, not the private knowledge of the approver."]},{"heading":"Privacy and retention","paragraphs":["Store the request sample and the evidence links in a controlled finance folder. Remove client names and matter details from the analysis file when they are not needed. If an example is shared, redact the client and the amount. Follow the firm's records policy for the retention period.","Limit access to the study team, the billing manager, and the finance approver. Do not circulate a requester-level list outside the management context. Aggregate the results before sharing them more broadly. The same rule applies to any client communication quoted in the report."]},{"heading":"Applying the result","paragraphs":["If missing evidence concentrates in one request type, add a required source field to that template. If it concentrates in small requests, decide whether a simplified documentation rule is appropriate and record the risk. If approved requests often lack evidence, add a pre-approval check that the source is attached. The fix should match the gap that the data shows.","Test the change on the next group of requests and compare the completeness rate and the approval rework with the baseline. A higher completeness rate with no increase in approval time is a clear gain. Record the result and set a review date. The goal is a request file that supports the decision without slowing it down."]},{"heading":"Review cadence","paragraphs":["Repeat the study quarterly while the request template is being revised, then move to a semiannual cycle. Keep the evidence levels and the request unit stable so the completeness comparison is valid. Report approved requests with missing evidence separately from rejected requests. A change in the approval threshold should be noted beside the rate.","Review the findings with the finance approver, the billing manager, and a relationship partner. Ask which evidence type is easiest to require at submission and which gap causes the most rework. Set one template change and a follow-up date. The next review should check whether completeness improved without slowing approvals."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/what-share-of-write-off-requests-lack-a-documented-client-basis.webp"},{"slug":"how-complete-are-billing-task-handoffs-at-the-end-of-a-shift","title":"How complete are billing task handoffs at the end of a shift?","summary":"A handoff completeness audit that scores the next action, owner, deadline, and evidence left for the person covering the next shift.","cluster":"Role design","finding":"A handoff should be scored on whether the next person can act without asking a question, not on how much narrative the outgoing person wrote.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how complete billing task handoffs are at the end of a shift. The unit is a handoff for one open task or queue, not a person's entire day. The purpose is to find the elements that are missing before an absence or a shift change creates a service gap. The result is a readiness assessment, not a performance review of the outgoing specialist.","Scope the audit to the tasks that remain open at the end of a shift and require action from the next person. Include prebill items, e-billing rejections, invoice follow-ups, and client questions. Exclude tasks that are fully closed or that have no next action. State the queues, the shifts, and the period included so the result is comparable."]},{"heading":"Defining a handoff","paragraphs":["A handoff is the record that tells the next person what is open, what has been done, what remains, and when it is due. It may live in a queue note, a shared document, or a structured task field. The handoff is complete when the next person can act without asking the outgoing person a question. A long note that omits the next action is not a complete handoff.","Distinguish a handoff from a status report. A status report describes what happened, while a handoff assigns the next step. Both can be useful, but the audit should focus on the actionability of the record. If the next person has to reconstruct the task from several messages, the handoff is incomplete even if the information exists somewhere."]},{"heading":"Required elements","paragraphs":["Define a fixed list of required elements: task or matter identifier, current state, next action, owner, due date, source or evidence link, and any known risk or dependency. Add the date and time of the handoff and the name of the outgoing person. Each element should be observable in the record. Keep the list short enough to score consistently.","Mark an element as conditional when it applies only to some tasks, such as a client contact or a vendor reference. A conditional element should not lower the score when it is not relevant. The scoring guide should state how conditional elements are handled. Record the list version so a later audit uses the same standard."]},{"heading":"Scoring","paragraphs":["Score each element as present, partial, or missing. Present means the next person can act on it without asking. Partial means the element is mentioned but lacks a name, date, link, or specific step. Missing means the element is absent or unusable. Define the levels with examples so two reviewers score the same handoff similarly.","Calculate a completeness score for each handoff and for the queue. Report the element-level results beside the total, because a queue can score well overall while every handoff misses the due date. Weight the elements only if the team has an explicit reason to do so. Otherwise, keep the score unweighted and transparent."]},{"heading":"Sampling","paragraphs":["Audit every handoff in scope when the number is small. If the queue is large, sample across shift types, task categories, and staff members. Include handoffs from busy and quiet shifts so the sample is not skewed by one difficult day. Draw the sample before reading the records to avoid selecting the most obvious gaps.","Review the version of the handoff that the next person actually saw, not an earlier draft. Record the handoff time and the time the next person first acted on it. If there are multiple copies, score the one in the shared queue. The audit should reflect the real coverage path."]},{"heading":"Verification","paragraphs":["Read the handoff and then compare it with the live task. Confirm that the next action matches the current state and that the due date is still accurate. Check that the evidence link opens and points to the right record. A handoff can look complete while the task has already changed. The verification step separates a document review from a readiness check.","For tasks with a client deadline, confirm that the next person understood the deadline and the escalation path. Ask the covering person to explain the task in one sentence without opening the original messages. If they cannot, the handoff is not actionable. Record the result as part of the audit evidence."]},{"heading":"Coding gaps","paragraphs":["Group gaps into missing next action, missing owner, missing deadline, missing evidence, unclear status, and dependency not recorded. Assign one primary gap per element and list secondary gaps when needed. The primary gap should point to the fix, such as a template field or a shift routine. Code the gap at the element level so the report is specific.","Have a second reviewer score a sample and compare the results. Resolve disagreements by reading the handoff and the live task together. Report the agreement rate. If a gap category is used inconsistently, revise the definition before the main review."]},{"heading":"Analysis","paragraphs":["Report the completeness score by handoff, the share missing each required element, and the number of critical gaps. A critical gap is one that would stop the next person from acting on a client deadline. Show the critical gaps first, even when the overall score is high. Include the number of handoffs in the sample.","Break the results down by queue, shift, and task type. A queue may have strong prebill handoffs and weak e-billing handoffs, which calls for a targeted fix. Compare the score with the time the next person needed to act. A high score with slow action may indicate that the record is complete but hard to find."]},{"heading":"Limits and sources of error","paragraphs":["The audit measures the record and the next person's ability to act, not the outgoing person's total contribution. A complete handoff can still fail if the systems are unavailable or the next person lacks training. Report the audit as one part of readiness. Pair it with a handoff drill when possible.","The scoring may reward longer notes even when the extra text is not useful. Read for actionability rather than length, and use examples to keep the standard consistent. Report the share of handoffs that required a follow-up question. That measure is a direct signal of whether the handoff worked."]},{"heading":"Privacy and retention","paragraphs":["Store the audit results with the team's continuity records. Remove client names and personal details from the scoring sheet when they are not needed. If a gap involves a named person, report the role rather than the individual in the group summary. Follow the firm's retention policy for the underlying handoff records.","Limit access to the handoffs to the people who need them for coverage. An audit does not require copying the full record into a report. Use the element-level result and a short description of the gap. The report should improve readiness without widening access to sensitive operating detail."]},{"heading":"Applying the result","paragraphs":["Fix critical gaps first, starting with the next action, owner, and deadline. Assign each gap to the person who can close it and set a date. A missing evidence link may need a filing fix, while a missing next action may need a template change. Do not treat every gap as a training issue.","Run a handoff drill on the weakest queue and record what the covering person could not do. Update the template with the findings and re-score the same elements. A team that closes the critical gaps and tests the result is better prepared than one with a high score and no drill. Set the next review date before the meeting ends."]},{"heading":"Review cadence","paragraphs":["Audit the handoffs before each major leave cycle and at least twice a year. Repeat the audit after a shift pattern change or a queue reorganization. Keep the required element list stable so the scores are comparable. Report the number of critical gaps beside the total so a high score does not hide a blocking issue.","Review the results with the team lead and the billing manager. Ask which gap would cause the most harm during an absence and which fix is feasible this quarter. Set one priority and a follow-up date. The next audit should include a handoff drill so the score is tested against the covering person's actual ability to act."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-08","thumbnail":"/thumbnails/november-08/how-complete-are-billing-task-handoffs-at-the-end-of-a-shift.webp"}];
